import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { first } from 'rxjs/operators';
import { AccountService, AlertService } from '@app/_services';
import { Account } from '@app/_models';

@Component({
  selector: 'app-accounts-list',
  templateUrl: './list.component.html',
  styleUrls: ['./list.component.less'],
  standalone: true,
  imports: [CommonModule, RouterModule]
})
export class ListComponent implements OnInit {
  accounts?: Account[];

  constructor(
    public accountService: AccountService,
    private alertService: AlertService
  ) { }

  ngOnInit() {
    this.accountService.getAll()
      .pipe(first())
      .subscribe({
        next: (accounts: any) => {
          this.accounts = accounts;
        },
        error: (error: any) => {
          this.alertService.error(error);
        }
      });
  }

  deleteAccount(id?: string) {
    if (!id) return;
    const account = this.accounts?.find(x => x.id === id);
    if (confirm('Are you sure you want to delete "' + account?.firstName + ' ' + account?.lastName + '"?')) {
      this.accountService.delete(id)
        .pipe(first())
        .subscribe({
          next: () => {
            this.accounts = this.accounts?.filter(x => x.id !== id);
            this.alertService.success('Account deleted successfully');
          },
          error: (error: any) => {
            this.alertService.error(error);
          }
        });
    }
  }
}
<div class="p-4">
  <h1>Manage Accounts</h1>

  <button routerLink="/admin/accounts/add" class="btn btn-sm btn-success mb-2">Add Account</button>

  <table class="table table-striped">
    <thead>
      <tr>
        <th>First Name</th>
        <th>Last Name</th>
        <th>Email</th>
        <th>Role</th>
        <th>Status</th>
        <th>Actions</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let account of accounts">
        <td>{{ account.firstName }}</td>
        <td>{{ account.lastName }}</td>
        <td>{{ account.email }}</td>
        <td>{{ account.role }}</td>
        <td><span class="badge" [ngClass]="account.isVerified ? 'bg-success' : 'bg-danger'">{{ account.isVerified ? 'Verified' : 'Not Verified' }}</span></td>
        <td>
          <a [routerLink]="['/admin/accounts/edit', account.id]" class="btn btn-sm btn-primary me-1">Edit</a>
          <button (click)="deleteAccount(account.id)" class="btn btn-sm btn-danger" [disabled]="account.id === accountService.accountValue?.id">Delete</button>
        </td>
      </tr>
    </tbody>
  </table>
</div>
